begin;
on conflict(id) do update set source_name=excluded.source_name,publisher=excluded.publisher,base_domain=excluded.base_domain,canonical_url=excluded.canonical_url,enabled=true,updated_at=now();

on conflict(id) do update set required_domains=excluded.required_domains,required_competencies=excluded.required_competencies,updated_at=now(),active=true;
commit;
